aws bedrock list-inference-profiles --region us-east-1 --query 'inferenceProfileSummaries[].inferenceProfileId' --output json | node -e "
const ids=JSON.parse(require('fs').readFileSync(0,'utf8'));
const v=(id)=>{const m=id.match(/claude-haiku-(\d+)-(\d+)(?:-|$)/);return m&&!/^\d{8}/.test(m[2])?+m[1]+ +m[2]/10:null};
const haiku=ids.filter(i=>/haiku/.test(i));if(!haiku.length){console.log('no Haiku profiles listed');process.exit(2)}
const newer=haiku.filter(i=>v(i)>5.5);
console.log(newer.length?'newer Haiku: '+newer.join(', '):'newest Haiku is 5.5 ('+haiku.length+' Haiku profiles)');
process.exit(newer.length?1:0)"
